expand_details.cypher:
MATCH (start:service {name: 'ts-auth-service'})
CALL apoc.path.expandConfig(start, {
    sequence: 'service,targets,pod,hosts,node,contains,container,uses,block IO device',
    minLevel: 0,
    maxLevel: 4,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;
